source("bscode-shinylive.R", local = TRUE)

library(shiny)
library(bslib)

if (!requireNamespace("DBI", quietly = TRUE) ||
    !requireNamespace("RSQLite", quietly = TRUE) ||
    !requireNamespace("tibble", quietly = TRUE)) {
  stop("This example requires the DBI, RSQLite, and tibble packages.")
}

sql_default <- paste(
  "SELECT model, mpg, cyl, wt",
  "FROM cars",
  "WHERE mpg > 20",
  "ORDER BY mpg DESC;",
  sep = "\n"
)

ui <- page_bscode(
  title = "SQL Lab",
  id = "main_nav",
  theme = bs_theme(
    primary = "#007ACC",
    bg = "#FFFFFF",
    fg = "#1E1E1E"
  ),

  nav_panel(
    "Query",
    value = "query",
    icon = icon("terminal"),
    layout_sidebar(
      fillable = TRUE,
      border = FALSE,
      sidebar = sidebar(
        title = "Explorer",
        width = 240,
        tags$strong("SQLite tables"),
        tags$ul(tags$li("cars"), tags$li("flowers")),
        hr(),
        actionButton(
          "run",
          "Run query",
          icon = icon("play"),
          class = "btn-primary w-100"
        ),
        p(
          class = "small text-body-secondary mt-2",
          "Both Run buttons execute the current editor contents."
        )
      ),
      layout_columns(
        col_widths = 12,
        row_heights = c(2, 1),
        fill = TRUE,
        class = "p-2",
        card(
          card_header(
            div(
              class = "d-flex align-items-center justify-content-between w-100",
              span("query.sql"),
              actionButton(
                "run_editor",
                NULL,
                icon = icon("play"),
                class = "btn-primary btn-sm",
                title = "Run query"
              )
            )
          ),
          input_code_editor(
            "sql",
            value = sql_default,
            language = "sql",
            height = "100%",
            theme_light = "vs-code-light",
            theme_dark = "vs-code-dark",
            fill = TRUE
          )
        ),
        card(
          card_header(textOutput("console_title", inline = TRUE)),
          card_body(
            div(
              class = "h-100 overflow-auto",
              verbatimTextOutput("result", placeholder = TRUE)
            ),
            fillable = TRUE
          )
        )
      )
    )
  ),

  nav_spacer(),

  nav_panel(
    "Help",
    value = "help",
    icon = icon("circle-question"),
    div(
      class = "p-4",
      h2("Try these queries"),
      tags$pre("SELECT * FROM flowers LIMIT 10;"),
      tags$pre("SELECT cyl, AVG(mpg) AS avg_mpg FROM cars GROUP BY cyl;")
    )
  )
)

server <- function(input, output, session) {
  con <- DBI::dbConnect(RSQLite::SQLite(), ":memory:")
  DBI::dbWriteTable(con, "cars", cbind(model = rownames(mtcars), mtcars))
  DBI::dbWriteTable(con, "flowers", iris)

  result <- reactiveVal(DBI::dbGetQuery(con, sql_default))
  status <- reactiveVal("Ready")

  run_query <- function() {
    query <- trimws(input$sql)
    allowed <- grepl("^(SELECT|WITH|PRAGMA)\\b", query, ignore.case = TRUE)

    if (!allowed) {
      status("Only SELECT, WITH, and PRAGMA queries are allowed in this example.")
      return()
    }

    tryCatch(
      {
        value <- DBI::dbGetQuery(con, query)
        result(value)
        status(sprintf("%s row(s)", nrow(value)))
      },
      error = function(error) status(conditionMessage(error))
    )
  }

  observeEvent(input$run, run_query())
  observeEvent(input$run_editor, run_query())

  output$result <- renderPrint({
    tibble::as_tibble(result())
  })

  output$console_title <- renderText(paste("Results ·", status()))

  session$onSessionEnded(function() {
    DBI::dbDisconnect(con)
  })
}

shinyApp(ui, server)

source("bscode-source.R", local = TRUE)

bscode_dependency <- function() {
  htmltools::htmlDependency(
    name = "bscode",
    version = "0.0.0.9002",
    src = c(href = "bscode"),
    stylesheet = "bscode.css",
    script = "bscode.js"
  )
}

.bscode_state <- new.env(parent = emptyenv())

`%||%` <- function(x, y) {
  if (is.null(x)) y else x
}

has_class <- function(x, class) {
  if (!inherits(x, "shiny.tag")) {
    return(FALSE)
  }

  classes <- htmltools::tagGetAttribute(x, "class") %||% ""
  class %in% strsplit(classes, "\\s+")[[1L]]
}

is_bscode_nav_panel <- function(x) {
  has_class(x, "tab-pane")
}

is_bscode_nav_spacer <- function(x) {
  has_class(x, "bslib-nav-spacer")
}

panel_label <- function(x) {
  label <- htmltools::tagGetAttribute(x, "title") %||%
    htmltools::tagGetAttribute(x, "data-value") %||%
    "panel"

  as.character(label)
}

warn_missing_icons <- function(items) {
  panels <- Filter(is_bscode_nav_panel, items)
  missing <- vapply(
    panels,
    function(panel) is.null(attr(panel, "_shiny_icon")),
    logical(1)
  )

  if (!any(missing) || isTRUE(.bscode_state$missing_icon_warning)) {
    return(invisible(NULL))
  }

  labels <- vapply(panels[missing], panel_label, character(1))
  warning(
    paste0(
      "Icons are recommended for page_bscode() navigation. ",
      "Using the first letter as a fallback for: ",
      paste(labels, collapse = ", "),
      "."
    ),
    call. = FALSE
  )

  .bscode_state$missing_icon_warning <- TRUE
  invisible(NULL)
}

prepare_panel_fill <- function(item, fillable) {
  if (!is_bscode_nav_panel(item)) {
    return(item)
  }

  value <- htmltools::tagGetAttribute(item, "data-value")
  should_fill <- isTRUE(fillable) ||
    (is.character(fillable) && !is.null(value) && value %in% fillable)

  if (!should_fill) {
    return(htmltools::tagAppendAttributes(item, class = "bscode-pane-scroll"))
  }

  item <- htmltools::tagAppendAttributes(item, class = "bscode-pane-fill")
  bslib::as_fill_carrier(item)
}

make_brand <- function(title, brand, nav_mode) {
  if (identical(brand, FALSE)) {
    return(NULL)
  }

  label <- if (is.character(title) && length(title) == 1L) title else "bscode"

  if (is.null(brand)) {
    if (!is.character(title) || length(title) != 1L || !nzchar(trimws(title))) {
      return(NULL)
    }

    brand <- if (identical(nav_mode, "sidebar")) {
      trimws(title)
    } else {
      substr(trimws(title), 1L, 1L)
    }
  }

  htmltools::div(
    class = "bscode-brand",
    title = label,
    `aria-label` = label,
    brand
  )
}

split_navset <- function(navset) {
  if (!inherits(navset, "shiny.tag")) {
    stop("Unable to build the bslib navigation container.", call. = FALSE)
  }

  children <- navset$children
  nav_index <- which(vapply(children, has_class, logical(1), class = "nav"))
  content_index <- which(vapply(children, has_class, logical(1), class = "tab-content"))

  if (length(nav_index) != 1L || length(content_index) != 1L) {
    stop(
      "Unable to locate the navigation and content elements produced by bslib::navset_pill().",
      call. = FALSE
    )
  }

  list(
    nav = children[[nav_index]],
    content = children[[content_index]]
  )
}

bscode_dependency <- function() {
  path <- system.file("www", package = "bscode")

  htmltools::htmlDependency(
    name = "bscode",
    version = as.character(utils::packageVersion("bscode")),
    src = c(file = path),
    stylesheet = "bscode.css",
    script = "bscode.js"
  )
}

#' A VS Code-inspired navigation page
#'
#' Creates a screen-filling bslib page whose navigation is displayed as either
#' a compact activity bar or a wider sidebar with icons and labels. The dots
#' must contain [bslib::nav_panel()] and [bslib::nav_spacer()] objects.
#'
#' @param ... Navigation items created by [bslib::nav_panel()] or
#'   [bslib::nav_spacer()].
#' @param header Optional UI displayed above every navigation panel.
#' @param title Window title and source of the default brand.
#' @param id Navigation input ID, compatible with [bslib::nav_select()].
#' @param selected Value of the initially selected panel.
#' @param position Position of the navigation: `"left"` or `"right"`.
#' @param nav_mode Navigation presentation: `"activity"` for icons only or
#'   `"sidebar"` for icons and labels.
#' @param nav_width Width of the navigation when `nav_mode = "sidebar"`.
#' @param size Navigation item size: `"sm"`, `"md"`, `"lg"`, or `"xl"`.
#' @param fillable `TRUE` to make every panel fill the viewport, `FALSE` to use
#'   normal scrolling, or a character vector containing panel values to fill.
#' @param fillable_mobile Whether the page fills the viewport on narrow screens.
#' @param tooltip_placement Tooltip placement in activity mode. `"auto"` uses
#'   the side opposite the navigation. Use `NULL` to disable tooltips.
#' @param theme A [bslib::bs_theme()] object. The default uses VS Code blue as
#'   the Bootstrap primary color.
#' @param brand Optional UI shown at the top of the navigation. `NULL` uses the
#'   first letter of a character `title` in activity mode and the full title in
#'   sidebar mode; `FALSE` removes the brand.
#' @param lang Language attribute passed to [bslib::page_fillable()].
#'
#' @return A Shiny page UI.
#' @export
page_bscode <- function(
  ...,
  header = NULL,
  title = NULL,
  id = NULL,
  selected = NULL,
  position = c("left", "right"),
  nav_mode = c("activity", "sidebar"),
  nav_width = "240px",
  size = "md",
  fillable = TRUE,
  fillable_mobile = TRUE,
  tooltip_placement = "auto",
  theme = bslib::bs_theme(primary = "#007ACC"),
  brand = NULL,
  lang = NULL
) {
  position <- match.arg(position)
  nav_mode <- match.arg(nav_mode)
  size <- match.arg(size, c("sm", "md", "lg", "xl"))

  nav_width <- tryCatch(
    htmltools::validateCssUnit(nav_width),
    error = function(error) {
      stop("`nav_width` must be a valid CSS unit, such as `240px` or `16rem`.", call. = FALSE)
    }
  )

  if (!is.null(tooltip_placement)) {
    tooltip_placement <- match.arg(
      tooltip_placement,
      c("auto", "top", "right", "bottom", "left")
    )
  }

  valid_fillable <-
    (is.logical(fillable) && length(fillable) == 1L && !is.na(fillable)) ||
    is.character(fillable)

  if (!valid_fillable) {
    stop("`fillable` must be TRUE, FALSE, or a character vector of panel values.", call. = FALSE)
  }

  items <- list(...)

  if (!length(items)) {
    stop("page_bscode() requires at least one nav_panel().", call. = FALSE)
  }

  valid <- vapply(
    items,
    function(item) is_bscode_nav_panel(item) || is_bscode_nav_spacer(item),
    logical(1)
  )

  if (!all(valid)) {
    item_names <- names(items) %||% rep("", length(items))
    named_invalid <- unique(item_names[!valid & nzchar(item_names)])
    unnamed_invalid <- which(!valid & !nzchar(item_names))
    details <- character()

    if (length(named_invalid)) {
      details <- c(
        details,
        paste0(
          "Unsupported argument(s): ",
          paste(sprintf("`%s`", named_invalid), collapse = ", "),
          "."
        )
      )
    }

    if (length(unnamed_invalid)) {
      details <- c(
        details,
        paste0(
          "Invalid unnamed item(s) at position(s): ",
          paste(unnamed_invalid, collapse = ", "),
          "."
        )
      )
    }

    stop(
      paste(
        c(
          details,
          "Every item in `...` must be created by bslib::nav_panel() or bslib::nav_spacer()."
        ),
        collapse = " "
      ),
      call. = FALSE
    )
  }

  warn_missing_icons(items)
  items <- lapply(items, prepare_panel_fill, fillable = fillable)

  navset <- do.call(
    bslib::navset_pill,
    c(items, list(id = id, selected = selected))
  )

  parts <- split_navset(navset)
  nav <- htmltools::tagAppendAttributes(parts$nav, class = "bscode-nav")
  content <- htmltools::tagAppendAttributes(
    parts$content,
    class = "bscode-tab-content"
  )
  content <- bslib::as_fill_carrier(content)

  navset$children <- list(
    htmltools::div(
      class = "bscode-activity-bar",
      make_brand(title, brand, nav_mode),
      nav
    ),
    htmltools::tags$main(
      class = "bscode-content",
      if (!is.null(header)) {
        htmltools::div(class = "bscode-header", header)
      },
      content
    )
  )

  shell <- htmltools::tagAppendAttributes(
    navset,
    class = paste(
      "bscode-shell",
      paste0("bscode-position-", position),
      paste0("bscode-nav-mode-", nav_mode),
      paste0("bscode-size-", size)
    ),
    style = htmltools::css(`--bscode-nav-width` = nav_width),
    `data-bscode-position` = position,
    `data-bscode-nav-mode` = nav_mode,
    `data-bscode-tooltip-placement` = tooltip_placement %||% "none"
  )
  shell <- bslib::as_fill_carrier(shell)

  bslib::page_fillable(
    class = "bscode-page",
    bscode_dependency(),
    shell,
    padding = 0,
    gap = 0,
    fillable_mobile = fillable_mobile,
    title = title,
    theme = theme,
    lang = lang
  )
}

html,
body {
  width: 100%;
  height: 100%;
}

.bscode-page {
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  margin: 0;
  overflow: hidden;
}

.bscode-page > .bscode-shell {
  flex: 1 1 auto;
  height: 100%;
  min-height: 0;
}

.bscode-shell {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--bs-body-bg);
}

.bscode-size-sm {
  --bscode-bar-width: 50px;
  --bscode-item-height: 48px;
  --bscode-icon-size: 1.15rem;
  --bscode-brand-icon-size: 1.4rem;
  --bscode-brand-font-size: 1.05rem;
  --bscode-letter-size: 1.35rem;
  --bscode-letter-font-size: 0.75rem;
}

.bscode-size-md {
  --bscode-bar-width: 58px;
  --bscode-item-height: 54px;
  --bscode-icon-size: 1.35rem;
  --bscode-brand-icon-size: 1.6rem;
  --bscode-brand-font-size: 1.2rem;
  --bscode-letter-size: 1.55rem;
  --bscode-letter-font-size: 0.85rem;
}

.bscode-size-lg {
  --bscode-bar-width: 68px;
  --bscode-item-height: 64px;
  --bscode-icon-size: 1.65rem;
  --bscode-brand-icon-size: 1.95rem;
  --bscode-brand-font-size: 1.4rem;
  --bscode-letter-size: 1.9rem;
  --bscode-letter-font-size: 1rem;
}

.bscode-size-xl {
  --bscode-bar-width: 80px;
  --bscode-item-height: 74px;
  --bscode-icon-size: 2rem;
  --bscode-brand-icon-size: 2.3rem;
  --bscode-brand-font-size: 1.65rem;
  --bscode-letter-size: 2.25rem;
  --bscode-letter-font-size: 1.15rem;
}

.bscode-position-left {
  flex-direction: row;
}

.bscode-position-right {
  flex-direction: row-reverse;
}

.bscode-activity-bar {
  display: flex;
  flex: 0 0 var(--bscode-bar-width);
  flex-direction: column;
  width: var(--bscode-bar-width);
  min-height: 0;
  background: var(--bs-primary);
  box-shadow: 1px 0 0 rgba(15, 23, 42, 0.12);
}

.bscode-position-right .bscode-activity-bar {
  box-shadow: -1px 0 0 rgba(15, 23, 42, 0.12);
}

.bscode-nav-mode-sidebar .bscode-activity-bar {
  flex-basis: var(--bscode-nav-width);
  width: var(--bscode-nav-width);
}

.bscode-brand {
  display: grid;
  flex: 0 0 var(--bscode-bar-width);
  place-items: center;
  width: var(--bscode-bar-width);
  height: var(--bscode-bar-width);
  color: rgba(255, 255, 255, 0.98);
  font-size: var(--bscode-brand-font-size);
  font-weight: 500;
  letter-spacing: -0.03em;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16);
  user-select: none;
}

.bscode-brand > svg,
.bscode-brand > i,
.bscode-brand > img {
  max-width: var(--bscode-brand-icon-size);
  max-height: var(--bscode-brand-icon-size);
}

.bscode-nav-mode-sidebar .bscode-brand {
  display: flex;
  flex-basis: var(--bscode-item-height);
  justify-content: flex-start;
  gap: 0.75rem;
  width: 100%;
  height: var(--bscode-item-height);
  padding: 0 1rem;
  overflow: hidden;
  font-size: 0.95rem;
  letter-spacing: 0;
  white-space: nowrap;
}

.bscode-nav-mode-sidebar .bscode-brand > svg,
.bscode-nav-mode-sidebar .bscode-brand > i,
.bscode-nav-mode-sidebar .bscode-brand > img {
  flex: 0 0 auto;
}

.bscode-nav-mode-sidebar .bscode-brand > span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.bscode-nav {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  flex-wrap: nowrap;
  width: 100%;
  min-height: 0;
  padding: 0;
  border-radius: 0;
}

.bscode-nav > .nav-item {
  width: 100%;
}

.bscode-nav .bslib-nav-spacer {
  margin-top: auto;
}

.bscode-nav .nav-link {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--bscode-bar-width);
  height: var(--bscode-item-height);
  padding: 0;
  border: 0;
  border-radius: 0;
  color: rgba(255, 255, 255, 0.68);
  background: transparent;
  font-size: 0;
}

.bscode-nav-mode-sidebar .bscode-nav .nav-link {
  display: flex;
  justify-content: flex-start;
  gap: 0.75rem;
  width: 100%;
  padding: 0 1rem;
  font-size: 0.9rem;
  text-align: left;
  white-space: nowrap;
}

.bscode-nav-mode-sidebar .bscode-nav-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bscode-position-left .bscode-nav .nav-link {
  border-left: 3px solid transparent;
}

.bscode-position-right .bscode-nav .nav-link {
  border-right: 3px solid transparent;
}

.bscode-nav .nav-link svg {
  width: var(--bscode-icon-size) !important;
  height: var(--bscode-icon-size) !important;
  max-width: var(--bscode-icon-size) !important;
  max-height: var(--bscode-icon-size) !important;
  font-size: var(--bscode-icon-size) !important;
  line-height: 1;
}

.bscode-nav .nav-link i,
.bscode-nav .nav-link img {
  width: var(--bscode-icon-size);
  height: var(--bscode-icon-size);
  max-width: var(--bscode-icon-size);
  max-height: var(--bscode-icon-size);
  font-size: var(--bscode-icon-size);
  line-height: 1;
}

.bscode-nav .nav-link > :not(.bscode-nav-label) {
  display: grid;
  place-items: center;
}

.bscode-nav-mode-sidebar .bscode-nav .nav-link > :not(.bscode-nav-label) {
  flex: 0 0 auto;
}

.bscode-nav .nav-link:hover,
.bscode-nav .nav-link:focus-visible {
  color: rgba(255, 255, 255, 0.98);
  background: rgba(255, 255, 255, 0.09);
}

.bscode-nav .nav-link.active {
  color: #fff;
  background: rgba(255, 255, 255, 0.13);
}

.bscode-position-left .bscode-nav .nav-link.active {
  border-left-color: #fff;
}

.bscode-position-right .bscode-nav .nav-link.active {
  border-right-color: #fff;
}

.bscode-letter-icon {
  display: grid;
  place-items: center;
  width: var(--bscode-letter-size);
  height: var(--bscode-letter-size);
  border: 1px solid currentColor;
  border-radius: 0.3rem;
  font-size: var(--bscode-letter-font-size);
  font-weight: 600;
}

.bscode-nav .nav-link[data-bscode-tooltip-placement]::after {
  position: absolute;
  z-index: 1080;
  content: attr(data-bscode-label);
  padding: 0.35rem 0.55rem;
  border: 1px solid rgba(32, 35, 38, 0.18);
  border-radius: 0.3rem;
  color: #202326;
  background: #ffffff;
  box-shadow: 0 2px 8px rgba(32, 35, 38, 0.18);
  font-size: 0.78rem;
  font-weight: 500;
  line-height: 1.2;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 100ms ease, visibility 100ms ease;
}

.bscode-nav .nav-link[data-bscode-tooltip-placement]:hover::after,
.bscode-nav .nav-link[data-bscode-tooltip-placement]:focus-visible::after {
  opacity: 1;
  visibility: visible;
}

.bscode-nav .nav-link[data-bscode-tooltip-placement="right"]::after {
  top: 50%;
  left: calc(100% + 8px);
  transform: translateY(-50%);
}

.bscode-nav .nav-link[data-bscode-tooltip-placement="left"]::after {
  top: 50%;
  right: calc(100% + 8px);
  transform: translateY(-50%);
}

.bscode-nav .nav-link[data-bscode-tooltip-placement="top"]::after {
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
}

.bscode-nav .nav-link[data-bscode-tooltip-placement="bottom"]::after {
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
}

.bscode-content {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: auto;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.bscode-header {
  flex: 0 0 auto;
  min-width: 0;
}

.bscode-tab-content {
  flex: 1 1 auto;
  width: 100%;
  height: auto;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.bscode-tab-content > .tab-pane {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.bscode-tab-content > .bscode-pane-fill.active {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.bscode-tab-content > .bscode-pane-scroll.active {
  overflow: auto;
}

@media (max-width: 600px) {
  .bscode-size-sm {
    --bscode-bar-width: 46px;
    --bscode-item-height: 44px;
    --bscode-icon-size: 1.05rem;
    --bscode-brand-icon-size: 1.25rem;
